20	import SeriesModel from '../../model/Series';
21	import createSeriesDataSimply from '../helper/createSeriesDataSimply';
22	import * as zrUtil from 'zrender/src/core/util';
23	import LegendVisualProvider from '../../visual/LegendVisualProvider';
24	import {
25	    SeriesOption,
26	    LineStyleOption,
27	    SeriesLabelOption,
28	    SymbolOptionMixin,
29	    ItemStyleOption,
30	    AreaStyleOption,
31	    OptionDataValue,
32	    StatesOptionMixin,
33	    OptionDataItemObject,
34	    SeriesEncodeOptionMixin,
35	    CallbackDataParams,
36	    DefaultStatesMixinEmphasis
37	} from '../../util/types';
38	import GlobalModel from '../../model/Global';
39	import SeriesData from '../../data/SeriesData';
40	import Radar from '../../coord/radar/Radar';
41	import {
42	    createTooltipMarkup, retrieveVisualColorForTooltipMarker
43	} from '../../component/tooltip/tooltipMarkup';
44	
45	type RadarSeriesDataValue = OptionDataValue[];
46	
47	interface RadarStatesMixin {
48	    emphasis?: DefaultStatesMixinEmphasis
49	}
50	export interface RadarSeriesStateOption<TCbParams = never> {
51	    lineStyle?: LineStyleOption
52	    areaStyle?: AreaStyleOption
53	    label?: SeriesLabelOption
54	    itemStyle?: ItemStyleOption<TCbParams>
55	}
56	export interface RadarSeriesDataItemOption extends SymbolOptionMixin,
57	    RadarSeriesStateOption<CallbackDataParams>,
58	    StatesOptionMixin<RadarSeriesStateOption<CallbackDataParams>, RadarStatesMixin>,
59	    OptionDataItemObject<RadarSeriesDataValue> {
60	}
61	
62	export interface RadarSeriesOption
63	    extends SeriesOption<RadarSeriesStateOption, RadarStatesMixin>,
64	    RadarSeriesStateOption,
65	    SymbolOptionMixin<CallbackDataParams>, SeriesEncodeOptionMixin {
66	    type?: 'radar'
67	    coordinateSystem?: 'radar'
68	
69	    radarIndex?: number
70	    radarId?: string
71	
72	    data?: (RadarSeriesDataItemOption | RadarSeriesDataValue)[]
73	}
74	
75	class RadarSeriesModel extends SeriesModel<RadarSeriesOption> {
76	
77	    static readonly type = 'series.radar';
78	    readonly type = RadarSeriesModel.type;
79	
80	    static dependencies = ['radar'];
81	
82	    coordinateSystem: Radar;
83	
84	    hasSymbolVisual = true;
85	
86	    // Overwrite
87	    init(option: RadarSeriesOption) {
88	        super.init.apply(this, arguments as any);
89	
90	        // Enable legend selection for each data item
91	        // Use a function instead of direct access because data reference may changed
92	        this.legendVisualProvider = new LegendVisualProvider(
93	            zrUtil.bind(this.getData, this), zrUtil.bind(this.getRawData, this)
94	        );
95	
96	    }
97	
98	    getInitialData(option: RadarSeriesOption, ecModel: GlobalModel): SeriesData {
99	        return createSeriesDataSimply(this, {
100	            generateCoord: 'indicator_',
101	            generateCoordCount: Infinity
102	        });
103	    }
104	
105	    formatTooltip(
106	        dataIndex: number,
107	        multipleSeries?: boolean,
108	        dataType?: string
109	    ) {
110	        const data = this.getData();
111	        const coordSys = this.coordinateSystem;
112	        const indicatorAxes = coordSys.getIndicatorAxes();
113	        const name = this.getData().getName(dataIndex);
114	        const nameToDisplay = name === '' ? this.name : name;
115	        const markerColor = retrieveVisualColorForTooltipMarker(this, dataIndex);
116	
117	        return createTooltipMarkup('section', {
118	            header: nameToDisplay,
119	            sortBlocks: true,
120	            blocks: zrUtil.map(indicatorAxes, axis => {
121	                const val = data.get(data.mapDimension(axis.dim), dataIndex);
122	                return createTooltipMarkup('nameValue', {
123	                    markerType: 'subItem',
124	                    markerColor: markerColor,
125	                    name: axis.name,
126	                    value: val,
127	                    sortParam: val
128	                });
129	            })
130	        });
131	    }
132	
133	    getTooltipPosition(dataIndex: number) {
134	        if (dataIndex != null) {
135	            const data = this.getData();
136	            const coordSys = this.coordinateSystem;
137	            const values = data.getValues(
138	                zrUtil.map(coordSys.dimensions, function (dim) {
139	                    return data.mapDimension(dim);
140	                }), dataIndex
141	            );
142	
143	            for (let i = 0, len = values.length; i < len; i++) {
144	                if (!isNaN(values[i] as number)) {
145	                    const indicatorAxes = coordSys.getIndicatorAxes();
146	                    return coordSys.coordToPoint(indicatorAxes[i].dataToCoord(values[i]), i);
147	                }
148	            }
149	        }
150	    }
151	
152	    static defaultOption: RadarSeriesOption = {
153	        // zlevel: 0,
154	        z: 2,
155	        colorBy: 'data',
156	        coordinateSystem: 'radar',
157	        legendHoverLink: true,
158	        radarIndex: 0,
159	        lineStyle: {
160	            width: 2,
161	            type: 'solid',
162	            join: 'round'
163	        },
164	        label: {
165	            position: 'top'
166	        },
167	        // areaStyle: {
168	        // },
169	        // itemStyle: {}
170	        symbolSize: 8
171	        // symbolRotate: null
172	    };
173	}
174	
175	export default RadarSeriesModel;

